// Seeded RNG (mulberry32) plus small helpers. Every random choice in the game
// goes through one of these so a seeded run is fully reproducible.
export function createRandom(seed) {
  let a = seed >>> 0;
  return function next() {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
