    setWidth('armorFill', Math.max(0, p.armor));
    setText('ammoMag', w.melee ? '—' : p.mag);
    setText('ammoRes', w.melee ? '' : ' / ' + p.reserve);
    setText('weaponName', w.name);
    setText('credits', '$' + p.credits);
