    for (const a of all) {
      if (!a.alive) continue;
      const d = Math.hypot(a.x - g.x, a.z - g.z);
      if (d > 20) continue;
      if (losBlocked(a.x, a.z, g.x, g.z)) continue;
      const face = facingFactor(a, g.x, g.z);
      const dur = Math.max(0.4, 2.8 * (1 - d / 20) * (0.35 + 0.65 * face));
