    game.heBoom = { x: g.x, z: g.z, at: performance.now() };
    sfx.explode();
    const w = { name: 'Frag Charge', armorPen: 0.8, killReward: 300 };
    for (const a of [game.player, ...game.bots]) {
      if (!a.alive) continue;
      const d = Math.hypot(a.x - g.x, a.z - g.z);
